/* Generated by scripts/build-tokens.mjs from tokens/palette.mjs. Do not edit. */

/*
 * The two stylesheets a compiled component needs and cannot ask for itself.
 *
 * A registry item ships `.tsx` files, and a `.tsx` file cannot declare that its classes come
 * from somewhere. So a DOM consumer who installs `@cubeui/toggle-chip` gets markup wearing
 * `cube-rn-view` and `animate-in` with nothing in their tree defining either, and the component
 * renders — unstyled, in the wrong direction, with no error anywhere to say why. This file is the
 * one thing every consumer installs, so it is where the two get said.
 *
 * `cubeui-reset.css` is the compiler's own, installed beside this file. React Native source
 * legitimately omits classes the DOM then needs, because Yoga supplies the defaults and CSS does
 * not: no RN author writes `flex-col`, because a `<View>` already stacks that way. On web
 * react-native-web closes that gap with a per-component base class, and a compiled component has
 * no react-native-web — this replaces it. 24 of the compiled components wear one of its classes.
 *
 * `tw-animate-css` is where `animate-in`, `fade-in-0`, `zoom-in-95` and `slide-in-from-*` live.
 * They are not core Tailwind utilities and never were: shadcn's own `init` writes this same import
 * into an app's stylesheet, which is why a component copied out of shadcn's registry appears to
 * work without declaring it. Four items here use them — `dialog`, `popover`, `select` and
 * `tooltip` — and what is lost without it is not the animation but the `data-[state]` rules
 * around it.
 *
 * Both are `@import` and not a `dependencies` entry per item, because the question is not which
 * component needs them — it is whether the stylesheet the app already loads defines the classes
 * its components name. `tw-animate-css` is still declared as a package, since a bare specifier
 * has to resolve to something installed.
 */
@import "tw-animate-css";
@import "./cubeui-reset.css";

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.269 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.371 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
}

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
}

/*
 * The reset a compiled component needs, and the reason the compiler cannot be only a rename.
 *
 * React Native source legitimately omits classes that the DOM then needs, because Yoga supplies
 * the defaults and CSS does not. `flex-direction` is the clearest case: a `<View>` stacks its
 * children vertically with nothing said, so no RN author ever writes `flex-col` — and the same
 * markup as a `<div>` is `display: block`, where the children stack for a different reason and
 * every `flex-1`, `items-center` and `gap-*` beside them stops meaning what it meant. Emitting
 * `<div class="rounded-lg border">` and calling it compiled would produce a tree that looks
 * nearly right and is wrong everywhere flex was load-bearing.
 *
 * On web today react-native-web closes that gap with a per-component base class of its own. A
 * compiled component has no react-native-web, so this stylesheet is what replaces it. The values
 * below are lifted from `react-native-web/dist/cjs/exports/{View,Text}/index.js` rather than
 * remembered, because the whole point is that the compiled tree lays out the way the RN one does.
 *
 * `@layer base` on purpose. The tokens stylesheet imports Tailwind's utilities *unlayered* — it
 * has to, because react-native-web's own base class is unlayered and would otherwise beat them —
 * so anything layered loses to a utility. That is exactly the precedence a reset wants: `p-6`
 * beats `padding: 0` here without the specificity fight that the react-native-web cascade needs a
 * comment to explain.
 */

@layer base {
  /*
   * A `<View>`. Four of these are what make RN-authored markup lay out at all: `display: flex`
   * and `flex-direction: column` because that is Yoga's default and nobody writes it, `flex-shrink:
   * 0` and `flex-basis: auto` because CSS flex items shrink below their content and Yoga's do not.
   */
  .cube-rn-view {
    align-content: flex-start;
    align-items: stretch;
    background-color: transparent;
    border: 0 solid;
    box-sizing: border-box;
    display: flex;
    flex-basis: auto;
    flex-direction: column;
    flex-shrink: 0;
    list-style: none;
    margin: 0;
    min-height: 0;
    min-width: 0;
    padding: 0;
    position: relative;
    text-decoration: none;
    z-index: 0;
  }

  /*
   * A `<Text>`. react-native-web also pins `color: black` and `font: 14px System` here, and this
   * deliberately does not: those emulate React Native, where nothing inherits and every `<Text>`
   * starts from the same place. On the DOM inheritance is the correct behaviour and the one a
   * consumer's own page styles expect — pinning them would make a compiled component the only
   * thing on the page that ignores the font it was dropped into. `white-space: pre-wrap` stays,
   * because RN treats the newlines in a string literal as text and HTML does not.
   */
  .cube-rn-text {
    background-color: transparent;
    border: 0 solid;
    box-sizing: border-box;
    list-style: none;
    margin: 0;
    padding: 0;
    position: relative;
    text-decoration: none;
    white-space: pre-wrap;
    word-wrap: break-word;
  }

  /*
   * A `<Pressable>`. It is a `<button>`, which arrives with a user-agent look — a border, a grey
   * background, centred text, the platform font — that no `<View>` has. Everything here is
   * undoing that, on top of the view reset the element also carries.
   */
  .cube-rn-pressable {
    appearance: none;
    color: inherit;
    cursor: pointer;
    font: inherit;
    text-align: inherit;
  }
}

/*
 * `pointerEvents`, which is a prop on native and a style on the web, and whose two "box" values
 * describe a view and its children disagreeing — something CSS says with two rules, not one value.
 *
 * Lifted rule for rule from `react-native-web/dist/cjs/exports/StyleSheet/compiler/index.js`,
 * including the `!important`, which is the one place this stylesheet copies react-native-web
 * rather than improving on it. The reason it is there: `pointerEvents` is written as a prop
 * precisely when the author needs it to win, and a utility class in the same `className` would
 * otherwise beat it. That is also why these four sit outside `@layer base` while everything above
 * sits inside it — a reset should lose to a utility, and this is not a reset.
 */
.cube-rn-pe-auto {
  pointer-events: auto !important;
}

.cube-rn-pe-none {
  pointer-events: none !important;
}

.cube-rn-pe-none > * {
  pointer-events: none;
}

/* Transparent to the pointer itself, while its children are not — a toast viewport, a tooltip
 * layer, anything that covers the screen to position something small. */
.cube-rn-pe-box-none {
  pointer-events: none !important;
}

.cube-rn-pe-box-none > * {
  pointer-events: auto;
}

/* The inverse: the view takes the pointer and its children do not. */
.cube-rn-pe-box-only {
  pointer-events: auto !important;
}

.cube-rn-pe-box-only > * {
  pointer-events: none;
}
